const campaign = $('Get Campaign').first().json;
const existingCount = $input.all().filter(it => it.json && it.json.id).length;

const goalMet = campaign.target_profile_count != null && existingCount >= campaign.target_profile_count;
const budgetMet = campaign.max_budget_usd != null && campaign.spent_usd >= campaign.max_budget_usd;
const exhausted = campaign.search_exhausted === true;
const safetyCap = campaign.next_search_page >= 200;

if (goalMet || budgetMet || exhausted || safetyCap) {
  return [];
}

return [{
  json: {
    campaign_id: campaign.id,
    search_goal: campaign.search_goal,
    target_profile_count: campaign.target_profile_count,
    max_budget_usd: campaign.max_budget_usd,
    spent_usd: campaign.spent_usd,
    next_search_page: campaign.next_search_page
  }
}];

if ($json.error) {
  throw new Error('OpenRouter request failed: ' + ($json.error.message || JSON.stringify($json.error)));
}
if (!$json.choices || !$json.choices[0]) {
  throw new Error('Unexpected OpenRouter response shape: ' + JSON.stringify($json));
}
const content = $json.choices[0].message.content;
const parsed = typeof content === 'string' ? JSON.parse(content) : content;
const state = $('Check Goal').first().json;
return {
  json: {
    ...state,
    search_params: parsed
  }
};

const state = $('Parse Search Params').first().json;
const rawResults = $input.all().map(it => it.json).filter(p => p && (p.linkedinUrl || p.profileUrl || p.publicIdentifier || p.url));

const extractLocation = (p) => (!p.location) ? null : (typeof p.location === 'string' ? p.location : (p.location.linkedinText || (p.location.parsed && p.location.parsed.text) || null));

const candidates = rawResults.map(p => ({
  linkedin_url: p.linkedinUrl || p.profileUrl || p.publicIdentifier || p.url || '',
  full_name: p.fullName || [p.firstName, p.lastName].filter(Boolean).join(' ') || null,
  headline: p.headline || null,
  location: extractLocation(p)
})).filter(c => c.linkedin_url);

return [{
  json: {
    ...state,
    candidates
  }
}];

const state = $('Extract Candidates').first().json;
const dedupMatches = $input.all().map(it => it.json).filter(m => m && m.linkedin_url);
const matchedByUrl = {};
for (const m of dedupMatches) {
  matchedByUrl[m.linkedin_url] = m;
}

const reuseList = [];
const enrichList = [];
for (const c of state.candidates) {
  const m = matchedByUrl[c.linkedin_url];
  if (m) {
    reuseList.push({ ...c, email: m.email, raw_data: m.raw_data });
  } else {
    enrichList.push(c);
  }
}

return [{
  json: {
    ...state,
    reuseList,
    enrichList
  }
}];

const state = $json;
return state.reuseList.map(r => ({
  json: {
    campaign_id: state.campaign_id,
    linkedin_url: r.linkedin_url,
    full_name: r.full_name,
    headline: r.headline,
    location: r.location,
    email: r.email,
    source: 'apify-reused',
    raw_data: r.raw_data
  }
}));

const items = $input.all();
for (const it of items) {
  if (it.json && it.json.error) {
    throw new Error('Enrich New failed: ' + (typeof it.json.error === 'string' ? it.json.error : JSON.stringify(it.json.error)));
  }
}

const state = $('Split Reuse vs Enrich').first().json;
const results = items.map(it => it.json).filter(p => p && (p.linkedinUrl || p.profileUrl || p.publicIdentifier || p.url));

const extractLocation = (p) => (!p.location) ? null : (typeof p.location === 'string' ? p.location : (p.location.linkedinText || (p.location.parsed && p.location.parsed.text) || null));

return results.map(p => ({
  json: {
    campaign_id: state.campaign_id,
    linkedin_url: p.linkedinUrl || p.profileUrl || p.publicIdentifier || p.url || '',
    full_name: p.fullName || [p.firstName, p.lastName].filter(Boolean).join(' ') || null,
    headline: p.headline || null,
    location: extractLocation(p),
    email: p.email || (Array.isArray(p.emails) && p.emails[0]) || null,
    source: 'apify',
    raw_data: p
  }
}));

const state = $input.first().json;
const reuseCount = state.reuseList.length;
const enrichCount = state.enrichList.length;
const cost = 0.10 + enrichCount * 0.01;
const newSpent = Math.round((state.spent_usd + cost) * 100) / 100;
const newNextPage = state.next_search_page + 1;
const newExhausted = state.candidates.length === 0;

return [{
  json: {
    campaign_id: state.campaign_id,
    spent_usd: newSpent,
    next_search_page: newNextPage,
    search_exhausted: newExhausted
  }
}];
